#!/usr/bin/env node
// Generates the user-facing slash-command skills in .claude/skills/ from one table.
// Gate/decision commands are human-only (disable-model-invocation: true); the UserPromptSubmit
// hook mints the signed token before the orchestrator ever sees the command.
// Agent definitions (pinned models, -retry variants) are generated by gen-agent-models.mjs.
//   node factory/cli/gen-command-skills.mjs           write the skills
//   node factory/cli/gen-command-skills.mjs --check   exit 1 if any generated skill is out of sync (no writes)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const F = 'node factory/cli/factory.mjs';
// Conversation language is configurable (FX-18: factory/config.json "humanLanguage", env FACTORY_HUMAN_LANGUAGE);
// the SessionStart hook injects the effective value. Generated text stays English.
const HL = "in the human's language (see `Human language` in the session context)";

const HUMAN_ONLY = (cmd) => `This command is a human decision. The UserPromptSubmit hook has already recorded (or refused) a signed token — look for the \`[factory-hook]\` note in context. If it says the decision was NOT recorded, tell the user ${HL} exactly what to type instead and stop.`;

const commands = [
  // ---- gates
  ['approve-concept', 'Human gate: approve and freeze the Game Concept Brief of the focused (or named) game.', '[game-id]', true,
    `${HUMAN_ONLY()}\n\nThen run \`${F} gate approve-concept\` (add \`--game <id>\` if one was named). On success: summarize ${HL} and continue with the \`factory-spec\` playbook (start the specification). On error: show the CLI message and the hint.`],
  ['approve-spec', 'Human gate: approve the final game specification.', '[game-id]', true,
    `${HUMAN_ONLY()}\n\nThen run \`${F} gate approve-spec\`. On success tell the user ${HL} that implementation starts only after they type \`/start-development\`.`],
  ['start-development', 'Human gate: freeze the approved spec and authorize implementation (scaffold, plan, parallel development).', '[game-id]', true,
    `${HUMAN_ONLY()}\n\nThen follow the \`factory-dev-loop\` playbook from step C1 (\`${F} gate start-development\`, plan, load, start the loop).`],
  ['approve-phase', 'Human gate: approve the current phase checkpoint and let the next phase start.', '[game-id]', true,
    `${HUMAN_ONLY()}\n\nThen run \`${F} gate approve-phase\` and continue the \`factory-dev-loop\` playbook for the next phase (or \`factory-release\` if this was the last phase).`],
  ['approve-playtest', 'Human gate: approve the release candidate after personal playtesting.', '[game-id]', true,
    `${HUMAN_ONLY()}\n\nThen run \`${F} gate approve-playtest\` and ask the user to type \`/approve-release <x.y.z>\` (suggest 1.0.0 for a first release).`],
  ['approve-release', 'Human gate: approve the release version (merge develop into main and tag), then package it.', '<x.y.z> [game-id]', true,
    `${HUMAN_ONLY()}\n\nThen run \`${F} gate approve-release --version <x.y.z>\` followed by \`${F} release package\`, and continue with \`factory-release\` F1 step 3.`],
  ['authorize-publish', 'Human gate: authorize exactly ONE Playgama external operation for the packaged build (draft | sandbox | catalog-update | traffic | store-config | referral).', '<op> [game-id]', true,
    `${HUMAN_ONLY()}\n\nThe token covers only the named operation for the current packaged build. Dispatch \`release-manager\` to perform exactly that operation (see \`factory-release\` F2) and report the real tool results. Do not perform any other operation.`],
  ['approve-spec-change', 'Human gate: approve an amended specification after a change request.', '[game-id]', true,
    `${HUMAN_ONLY()}\n\nThen run \`${F} spec refreeze\`. If tasks are affected, have tech-architect produce a plan amendment and load it with \`${F} plan load <file> --amend\`.`],
  ['retry-task', 'Human decision: grant a BLOCKED task two more attempts.', '<TASK-ID> [game-id]', true,
    `${HUMAN_ONLY()}\n\nThen run \`${F} task retry <TASK-ID>\` and restart it in the dev loop with \`${F} task start <TASK-ID>\`: dispatch exactly the agent it prints as \`Dispatch to\` (the \`-retry\` variant for attempts >= 2), never pass model or effort, and include the agreed resolution in the agent prompt.`],
  ['abandon-task', 'Human decision: abandon a BLOCKED task (its dependents must be re-planned).', '<TASK-ID> [game-id]', true,
    `${HUMAN_ONLY()}\n\nThen run \`${F} task abandon <TASK-ID>\` and have tech-architect re-plan the dependent tasks (\`plan load --amend\`).`],
  ['abandon-game', 'Human gate: abandon a draft game before development (IDEATION, CONCEPT_APPROVED, SPEC_DRAFT or SPEC_APPROVED); then /archive-game.', '[game-id] <reason>', true,
    `${HUMAN_ONLY()}\n\nThen run \`${F} gate abandon-game --game <id> --reason "<reason>"\` with the game named in the note (the focused game unless the FIRST word was a game id) and the reason the user typed, quoted. On success tell the user ${HL} that the game is ABANDONED and that \`/archive-game\` archives it. On error show the CLI message and the hint. Games in development or later are never abandoned.`],
  ['archive-game', 'Human gate: archive a released or abandoned game (production records into archive/ and the game repo).', '[game-id]', true,
    `${HUMAN_ONLY()}\n\nThen run \`${F} gate archive-game\` (add \`--game <id>\` if one was named) and report the archive path. Released games (PACKAGED, PUBLICATION_PREPARED) go to \`archive/<id>/<version>/production/\`; abandoned drafts go to \`archive/<id>/abandoned-<YYYYMMDD>/\` (production records + design). A draft that is not ABANDONED yet is refused: the user types \`/abandon-game <reason>\` first.`],
  // ---- decisions
  ['reject-phase', 'Human decision: reject the current phase checkpoint with a reason.', '<reason>', true,
    `${HUMAN_ONLY()}\n\nThen run \`${F} phase reject --reason "<reason>"\`, have tech-architect write corrective tasks for the current phase, load them with \`plan load --amend\` and continue the dev loop.`],
  ['request-changes', 'Human decision: request corrections or additional testing in the current phase.', '<text>', true,
    `${HUMAN_ONLY()}\n\nIf the phase is at CHECKPOINT run \`${F} phase reject --reason "<text>"\` first. Have tech-architect convert the request into corrective/test tasks (\`plan load --amend\`), continue the dev loop, and checkpoint again.`],
  ['pause', 'Human decision: pause the focused game (no new tasks start).', '[game-id]', true,
    `${HUMAN_ONLY()}\n\nRun \`${F} pause\`. Running agents may finish; submit their work but start nothing new. Confirm ${HL}.`],
  ['resume', 'Human decision: resume a paused game.', '[game-id]', true,
    `${HUMAN_ONLY()}\n\nRun \`${F} resume\`, then \`${F} recover\` and continue from the next permitted actions.`],
  ['modify-requirements', 'Human decision: open a change request against the approved specification.', '<text>', true,
    `${HUMAN_ONLY()}\n\nFollow the change-request section of the \`factory-spec\` playbook (\`${F} spec change-request\`).`],
  ['reject-playtest', 'Human decision: reject the release candidate with the issues found in playtesting.', '<issues>', true,
    `${HUMAN_ONLY()}\n\nRun \`${F} playtest reject --reason "<issues>"\` (adds a corrective phase) and follow \`factory-release\` step E5.`],
  // ---- informational / flow (model may also invoke)
  ['game-new', 'Start ideation for a new game: discuss the idea, then register it and run the ideation playbook.', '<idea or working title>', false,
    `Load the \`factory-ideation\` playbook and start Mode A with the idea in the arguments. Converse with the user ${HL}.`],
  ['game-status', 'Show production status of the factory or one game, with the next permitted actions.', '[game-id]', false,
    `Run \`${F} status\` (or \`${F} status --game <id>\`) and summarize ${HL}: mode, phase, running tasks and agents, failed/blocked tasks, pending reviews, pending human decisions, next permitted action. Quote numbers from the output only.`],
  ['game-focus', 'Switch the orchestrator focus to another game.', '<game-id>', false,
    `Run \`${F} game focus <game-id>\` then \`${F} status\` and summarize ${HL}.`],
  ['prepare-publication', 'Prepare the Playgama publication packet for a packaged game (no external changes).', '[game-id]', false,
    'Follow `factory-release` F1 step 3: run `node factory/cli/factory.mjs publish covers` (real screenshots of the packaged build), dispatch release-manager for release notes and the publication packet that references those covers, then run `node factory/cli/factory.mjs publish prepare`. Make no Playgama write calls.'],
  ['factory-metrics', 'Show production metrics (cycle times, attempts, rejection rates, gate latency, tokens).', '', false,
    `Run \`${F} metrics\` and summarize ${HL}: throughput, cycle times, first-pass rate, rework, bottlenecks. Quote only real numbers.`],
];

/**
 * The generated skills as `{ name: SKILL.md text }` (pure; no writes).
 * @returns {Record<string, string>}
 */
export function renderCommandSkills() {
  /** @type {Record<string, string>} */
  const out = {};
  for (const [name, description, hint, humanOnly, body] of commands) {
    const fm = ['---', `name: ${name}`, `description: ${JSON.stringify(description)}`];
    if (hint) fm.push(`argument-hint: "${hint}"`);
    if (humanOnly) fm.push('disable-model-invocation: true');
    fm.push('---');
    out[String(name)] = `${fm.join('\n')}\n\n# /${name}\n\nArguments: $ARGUMENTS\n\n${body}\n`;
  }
  return out;
}

/** Names of generated skills whose SKILL.md on disk differs from the generator output. */
export function staleCommandSkills(root = ROOT) {
  return Object.entries(renderCommandSkills())
    .filter(([name, text]) => {
      const file = path.join(root, '.claude', 'skills', name, 'SKILL.md');
      return !fs.existsSync(file) || fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n') !== text;
    })
    .map(([name]) => name);
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain && process.argv.includes('--check')) {
  const stale = staleCommandSkills();
  if (stale.length) {
    console.error(`out of sync (run node factory/cli/gen-command-skills.mjs): ${stale.join(', ')}`);
    process.exit(1);
  }
  console.log(`${commands.length} command skills in sync`);
} else if (isMain) {
  for (const [name, text] of Object.entries(renderCommandSkills())) {
    const dir = path.join(ROOT, '.claude', 'skills', name);
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, 'SKILL.md'), text);
  }
  console.log(`generated ${commands.length} command skills`);
}
